mapper.select:
SELECT t.id,t.api_code,t.config_id,t.file_id,t.clean_type as fileType,t.test_result,t.clean_status,t.create_time,t.update_time,c.field_config_show as ruleCondition FROM b_marketing_clean_data_task t left join b_marketing_data_file_config c on t.config_id = c.id
t.auto_clean_way_type=0
AND t.clean_type=#{fileType}
AND t.clean_status=#{status}
AND t.api_code=#{apiCode}
order by t.create_time desc

mapper.update:
update b_marketing_clean_data_task
set clean_status=#{cleanStatus}
where id=#{id}
